<script setup>
import {computed,ref,reactive,onMounted,onBeforeUnmount,watch} from 'vue';
import Panel from './components/Panel.vue';
import Icon from './components/Icon.vue';
import TwinScene from './components/TwinScene.vue';
import TwinChart from './components/TwinChart.vue';
import FloorMap from './components/FloorMap.vue';
import LoginView from './components/LoginView.vue';
import {api,isPublicDemo} from './auth.js';
import {assetUrl} from './urls.js';
import {building,spaces,spaceById,rooms,exits,connections} from './twin/building.js';
import {createTwin,startTwin,tick,metrics,findRoute,toggleExit,studentAction,event,compareStrategies,nearestDoor} from './twin/state.js';
import {parseFieldCsv,interfaceContract} from './twin/adapters.js';
const twin=reactive(createTwin());
const user=ref(null),authReady=ref(false);
const page=ref('command'),teacherTab=ref('演练管理'),floor=ref(3),sceneMode=ref('building'),layer=ref('overview'),selected=ref('R302');
const studentView=ref('third'),showGuide=ref(true);
const nearbyRoom=computed(()=>nearestDoor(twin));
watch(()=>twin.student.floor,f=>{if(page.value==='student')floor.value=f;});
const now=ref(new Date()),notice=ref(''),modal=ref(null),comparison=ref(null),comparing=ref(false),query=ref(''),statusFilter=ref('全部演练');
const replayIndex=ref(0),replayPlaying=ref(false),replaySpeed=ref(1),modelUrl=ref(assetUrl('/models/dormitory.glb')),modelStatus=ref('加载中');
const fdsName=ref(''),records=ref([]),params=reactive({name:'宿舍楼火灾应急疏散演练',source:'R302',strategy:'balanced',seed:42});
const overview=computed(()=>metrics(twin)),risk=computed(()=>twin.fields[selected.value]),source=computed(()=>spaceById[twin.fireSource]);
const maxRisk=computed(()=>spaces.reduce((a,b)=>twin.fields[a.id].risk>twin.fields[b.id].risk?a:b)),currentRisk=computed(()=>twin.fields[maxRisk.value.id]);
const studentField=computed(()=>twin.fields[twin.student.node]),studentRoute=computed(()=>findRoute(twin.student.node,twin));
const routeDistance=computed(()=>studentRoute.value?.reduce((n,id,i)=>i?n+(connections.find(e=>[e.a,e.b].includes(id)&&[e.a,e.b].includes(studentRoute.value[i-1]))?.length||0):0,0)??null);
const replay=computed(()=>twin.snapshots[replayIndex.value]||null);
const rows=computed(()=>[...(!twin.finished?[{id:'current',name:params.name,scene:building.name,count:286,status:twin.running?'进行中':twin.time?'已暂停':'计划中',date:'当前会话',score:null}]:[]),...records.value].filter(r=>(statusFilter.value==='全部演练'||r.status===statusFilter.value)&&`${r.name}${r.scene}`.includes(query.value)));
const studentScore=computed(()=>{const st=twin.student;return Math.max(0,Math.min(100,(st.escaped?60:0)+(st.crouching?10:0)+(st.towel?10:0)+Math.min(10,st.actions.filter(a=>['door','help'].includes(a.type)).length*5)+Math.max(0,10-st.exposure)));});
const nav=[{id:'command',label:'数字孪生',icon:'building'},{id:'student',label:'学生演练端',icon:'walk'},{id:'teacher',label:'教师管理后台',icon:'calendar'},{id:'review',label:'预案优化与复盘',icon:'chart'}];
const teacherMenu=[['home','首页总览'],['calendar','演练管理'],['map','场景管理'],['people','学生管理'],['report','评分报告'],['shield','预案管理'],['settings','系统设置']];
const format=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const danger=v=>v>.6?'高风险':v>.25?'中高风险':v>.1?'中等':'正常';
const pick=id=>{selected.value=id;floor.value=spaceById[id].floor;};
function changeFloor(f){floor.value=f;selected.value=`R${f}02`;sceneMode.value='floor';}
function focusPersonFloor(f,id){floor.value=f;selected.value=id;sceneMode.value='floor';}
function activateLayer(value){layer.value=layer.value===value?'overview':value;if(layer.value==='smoke'||layer.value==='routes')sceneMode.value='floor';else if(layer.value==='people')sceneMode.value='building';}
let timer,clockTimer,replayAccumulator=0,simAccumulator=0,lastTime=performance.now(),saved=false,toastTimer;
function toast(message){notice.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.value='',4200);}
function navigate(id){page.value=id;if(id==='review'){replayIndex.value=Math.max(0,twin.snapshots.length-1);sceneMode.value='floor';layer.value='heat';}else if(id==='command'){sceneMode.value='building';layer.value='overview';}else if(id==='student')floor.value=twin.student.floor;}
function reset(){Object.assign(twin,createTwin({source:params.source,seed:Number(params.seed),strategy:params.strategy}));saved=false;comparison.value=null;fdsName.value='';replayIndex.value=0;replayPlaying.value=false;selected.value=params.source;floor.value=source.value.floor;}
function start(){if(twin.finished){toast('请重置或新建演练后启动');return;}if(page.value==='student')twin.student.participating=true;startTwin(twin);}
function finish(){if(!twin.time){toast('请先启动演练');return;}twin.running=false;twin.finished=true;event(twin,'演练结束','教师手动结束本次演练');saveResult();}
async function saveResult(){if(saved)return;saved=true;const m=metrics(twin),record={id:Date.now(),name:params.name,scene:building.name,count:m.count,status:'已完成',date:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),score:m.score,metrics:m};records.value.unshift(record);try{await api('/api/records',record);}catch{toast('服务保存失败，当前记录仍可导出');}}
async function onLogin(value){user.value=value;navigate(value.role==='student'?'student':value.role==='teacher'?'teacher':'command');try{records.value=(await api('/api/records')).records;}catch{records.value=[];}}
async function logout(){try{await api('/api/auth/logout',{});}catch{}reset();records.value=[];user.value=null;}
function download(value,name,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportTwin(){download({building,config:{...params},source:twin.dataSource,fields:twin.fields,agents:twin.agents,student:twin.student,events:twin.events,history:twin.history,snapshots:twin.snapshots,result:overview.value,comparison:comparison.value},'campus-twin-drill.json');toast('完整演练记录已导出');}
function act(type){const error=studentAction(twin,type);toast(error||(twin.running?'操作已记录':'探索操作已执行，尚未计分'));}
function createDrill(){reset();modal.value=null;page.value='command';sceneMode.value='building';toast('新演练已创建，点击启动演练开始');}
function compare(){if(comparing.value)return;comparing.value=true;setTimeout(()=>{try{comparison.value=compareStrategies({source:params.source,seed:Number(params.seed),count:286});toast('A/B对比已完成：相同建筑、火源、人数和随机种子');}catch(e){toast(e.message);}finally{comparing.value=false;}},50);}
async function importFds(e){const file=e.target.files[0];if(!file)return;try{if(file.size>15*1048576)throw new Error('CSV文件不能超过15MB');const data=parseFieldCsv(await file.text());reset();twin.fds=data;twin.dataSource='fds';fdsName.value=file.name;event(twin,'数据接入',`导入场数据：${data.spaceCount}个空间，${data.frames.length}帧`);toast(`已导入 ${file.name}`);}catch(err){toast(err.message);}e.target.value='';}
function importModel(e){const file=e.target.files[0];if(!file)return;if(file.size>60*1048576){toast('模型上限60MB');return;}if(modelUrl.value.startsWith('blob:'))URL.revokeObjectURL(modelUrl.value);modelUrl.value=URL.createObjectURL(file);modelStatus.value='加载中';modal.value=null;page.value='command';toast('正在检查楼层语义；替换模型需与当前建筑坐标和空间映射一致');e.target.value='';}
function report(row){modal.value=row.id==='current'?'score':{type:'report',row};}
const localToday=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}).split('-').map(Number);
const month=ref(new Date(localToday[0],localToday[1]-1,1)),selectedDay=ref(localToday[2]);
function today(){month.value=new Date(localToday[0],localToday[1]-1,1);selectedDay.value=localToday[2];}
const calendarCells=computed(()=>{const start=(new Date(month.value.getFullYear(),month.value.getMonth(),1).getDay()+6)%7,days=new Date(month.value.getFullYear(),month.value.getMonth()+1,0).getDate();return Array.from({length:42},(_,i)=>i>=start&&i<start+days?i-start+1:null);});
function changeMonth(delta){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+delta,1);}
onMounted(async()=>{try{const result=await api('/api/auth/session');await onLogin(result.user);}catch{}finally{authReady.value=true;}clockTimer=setInterval(()=>now.value=new Date(),1000);timer=setInterval(()=>{const current=performance.now(),dt=Math.min(.5,(current-lastTime)/1000);lastTime=current;if(user.value&&twin.running){simAccumulator+=dt;while(simAccumulator>=.2){tick(twin,.2);simAccumulator-=.2;}}else simAccumulator=0;if(twin.finished&&!saved)saveResult();if(replayPlaying.value&&twin.snapshots.length){replayAccumulator+=dt*replaySpeed.value;if(replayAccumulator>=2){replayAccumulator=0;if(replayIndex.value<twin.snapshots.length-1)replayIndex.value++;else replayPlaying.value=false;}}},200);});
onBeforeUnmount(()=>{clearInterval(timer);clearInterval(clockTimer);clearTimeout(toastTimer);if(modelUrl.value.startsWith('blob:'))URL.revokeObjectURL(modelUrl.value);});
</script>

<template>
 <LoginView v-if="authReady&&!user" @login="onLogin"/>
 <div v-else-if="!authReady" class="auth-loading">正在连接校园应急平台…</div>
 <div v-else class="app-shell" :class="'page-'+page">
  <header class="masthead">
   <div class="institution"><img :src="assetUrl('/assets/campus-logo.png')" alt="校园徽标"><div><b>XX 大学</b><small>智慧校园 · 平安校园</small></div></div>
   <h1>校园消防数字孪生应急疏散决策系统<span v-if="page!=='command'">{{page==='student'?'学生演练端':page==='teacher'?'教师管理后台':'预案优化与复盘分析中心'}}</span></h1>
   <div class="mast-meta"><span>{{now.toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}}　{{now.toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})}}</span><div><Icon name="shield"/><small>{{isPublicDemo?'公开演示模式':'软件演练模式'}}</small></div></div>
  </header>
  <nav class="top-nav" aria-label="主要功能"><div class="nav-buttons"><button v-for="item in nav.filter(n=>user.role!=='student'||n.id!=='teacher')" :key="item.id" :class="{active:page===item.id}" @click="navigate(item.id)"><Icon :name="item.icon"/>{{item.label}}</button></div><div class="system-state"><span><Icon name="check"/>{{modelStatus==='就绪'?'模型已加载':modelStatus}}</span><span><Icon name="cloud"/>{{twin.dataSource==='fds'?'外部场数据':'软件仿真'}}</span><button class="text-button" @click="modal='model'">模型与接口</button><button class="text-button" @click="logout">{{user.name}} · 退出</button></div></nav>
  <main v-if="page==='command'" class="command-layout">
   <aside class="left-rail">
    <Panel title="建筑信息" tag="BUILDING"><div class="building-summary"><div class="building-glyph"><Icon name="building"/></div><div><h3>{{building.name}}</h3><p><Icon name="map"/>东校区 · 学生生活区</p></div></div><dl class="data-rows"><div><dt>建筑层数</dt><dd>6 <small>层</small></dd></div><div><dt>建筑尺寸</dt><dd>48 × 18 <small>m</small></dd></div><div><dt>演练人数</dt><dd>{{overview.count}} <small>人</small></dd></div><div><dt>出口数量</dt><dd>4 <small>个</small></dd></div></dl><div class="source-foot">参考图参数化建模 · 尺寸假设可查看</div></Panel>
    <Panel title="灾情态势" tag="FIRE STATUS"><div class="fire-position"><Icon name="fire"/><span>火源位置</span><b>{{source.name}}</b><small>{{source.floor}}层</small></div><div class="gauge-row"><span>风险等级</span><b class="orange">{{danger(risk.risk)}}</b><progress :value="risk.risk" max="1" class="red-progress"/></div><div class="gauge-row"><span>当前温度</span><b class="yellow">{{risk.temperature.toFixed(1)}}℃</b><progress :value="Math.min(1,(risk.temperature-22)/110)" max="1"/></div><div class="gauge-row"><span>烟气指数</span><b>{{risk.smoke.toFixed(2)}}</b><progress :value="risk.smoke" max="1"/></div><div class="gauge-row"><span>危险区域</span><b class="red">{{danger(currentRisk.risk)}}</b><small>{{maxRisk.name}}</small></div><select v-model="selected" aria-label="监测区域"><option v-for="r in spaces.filter(n=>n.floor===floor)" :value="r.id">{{r.name}}</option></select></Panel>
    <Panel title="仿真与通道状态" tag="TWIN STATE"><div class="engine-row"><Icon name="layers"/><span>空间语义模型</span><b class="green">{{spaces.length}} 个空间</b></div><div class="engine-row"><Icon name="fire"/><span>火烟数据源</span><b>{{twin.dataSource==='fds'?'CSV 场数据':'软件扩散模型'}}</b></div><div class="engine-row"><Icon name="walk"/><span>人员疏散</span><b class="cyan">动态 A* / 多智能体</b></div><div class="exit-controls"><button v-for="exit in exits" @click="toggleExit(twin,exit.id)" :class="{blocked:twin.blocked.includes(exit.id)}"><Icon name="exit"/>{{exit.name}}<span>{{twin.blocked.includes(exit.id)?'封闭':'开放'}}</span></button></div></Panel>
    <Panel title="楼层导航" tag="FLOORS"><div class="floor-table"><button v-for="f in [...overview.floors].reverse()" @click="changeFloor(f.floor)" :class="{active:floor===f.floor}"><b>{{f.floor}}F</b><span>学生宿舍</span><strong :class="f.risk>.25?'red':f.risk>.1?'yellow':'green'">{{danger(f.risk)}}</strong></button></div></Panel>
   </aside>
   <div class="main-stage">
    <div class="scene-panel"><div class="scene-title"><h2>{{building.name}} · {{sceneMode==='building'?'三维数字孪生模型':sceneMode==='exterior'?'完整建筑外观':`${floor}F 楼层剖切`}}</h2><span class="live-tag"><i/>{{twin.running?'演练运行中':twin.finished?'演练已结束':twin.time?'演练已暂停':'场景就绪'}} {{format(twin.time)}}</span></div>
     <TwinScene :twin="twin" :floor="floor" :mode="sceneMode" :layer="layer" :selected-space="selected" :model-url="modelUrl" @select="pick" @focus-floor="focusPersonFloor" @loaded="modelStatus='就绪'" @error="modelStatus='模型异常'"/>
     <div class="floor-switch"><button v-for="f in [6,5,4,3,2,1]" @click="changeFloor(f)" :class="{active:floor===f}">{{f}}F</button></div><div class="compass"><Icon name="map"/><span>N</span></div>
     <div class="scene-bottom"><div class="scene-tabs"><button :class="{active:sceneMode==='building'}" @click="sceneMode='building'">整体剖面</button><button :class="{active:sceneMode==='floor'}" @click="sceneMode='floor'">楼层剖切</button><button :class="{active:sceneMode==='exterior'}" @click="sceneMode='exterior'">完整外观</button><button :class="{active:layer==='smoke'}" :aria-pressed="layer==='smoke'" @click="activateLayer('smoke')">烟气模拟</button><button :class="{active:layer==='people'}" :aria-pressed="layer==='people'" @click="activateLayer('people')">人员定位</button><button :class="{active:layer==='routes'}" :aria-pressed="layer==='routes'" @click="activateLayer('routes')">疏散路线</button></div></div>
    </div>
    <div class="stage-controls"><button class="primary" @click="start" :disabled="twin.finished"><Icon :name="twin.running?'pause':'play'"/>{{twin.running?'暂停演练':twin.time?'继续演练':'启动演练'}}</button><button @click="reset"><Icon name="back"/>重置</button><button @click="finish"><Icon name="report"/>结束评分</button><button @click="exportTwin"><Icon name="download"/>导出记录</button><span>{{twin.dataSource==='fds'?fdsName:'算法状态与画面实时同步'}}</span></div>
    <div class="bottom-analysis"><Panel title="疏散趋势分析"><TwinChart kind="trend" :data="twin.history"/></Panel><Panel title="各楼层风险指数"><div class="risk-bars"><div v-for="f in [...overview.floors].sort((a,b)=>b.risk-a.risk)"><b>{{f.floor}}F</b><progress :value="f.risk" max="1" :class="f.risk>.25?'red-progress':''"/><strong>{{Math.round(f.risk*100)}}</strong><small>{{danger(f.risk)}}</small></div></div></Panel><Panel title="演练完成率 / 疏散效率"><div class="completion"><TwinChart kind="donut" :value="overview.completion*100"/><div class="donut-label"><b>{{Math.round(overview.completion*100)}}%</b><small>演练完成率</small></div></div><div class="completion-meta"><span>平均疏散时间 <b>{{(overview.time/60).toFixed(1)}} min</b></span><span>规则评分 <b>{{overview.score.toFixed(1)}} 分</b></span></div></Panel></div>
   </div>
   <aside class="right-rail"><Panel title="实时疏散指标" tag="LIVE"><div class="kpi-grid"><div v-for="k in [{icon:'people',name:'在楼人数',value:overview.remaining,color:'cyan'},{icon:'walk',name:'已疏散人数',value:overview.escaped,color:'green'},{icon:'alert',name:'暂无路径',value:overview.trapped,color:'red'},{icon:'time',name:'平均疏散时间',value:(overview.time/60).toFixed(1),color:'cyan'}]" :class="k.color"><Icon :name="k.icon"/><span>{{k.name}}</span><b>{{k.value}}<small>{{k.icon==='time'?'min':'人'}}</small></b></div></div><div class="warning-box"><Icon name="fire"/><div><b>最高风险区域</b><h3>{{maxRisk.name}}</h3><span>温度 {{currentRisk.temperature.toFixed(1)}}℃　烟气 {{currentRisk.smoke.toFixed(2)}}</span></div></div></Panel>
    <Panel title="动态疏散路径建议"><template #action><button class="text-button" @click="navigate('student')">进入演练 <Icon name="next"/></button></template><div class="recommended-exit"><Icon name="walk"/><div><small>当前推荐出口</small><h3>{{studentRoute?spaceById[studentRoute.at(-1)].name:'暂无安全路径'}}</h3><span>动态权重 · 风险与拥堵协同</span></div><b class="green">{{routeDistance===null?'—':Math.round(routeDistance)}} <small>m</small></b></div><div class="alt-exit" v-for="exit in exits"><span>{{exit.name}}</span><span :class="twin.blocked.includes(exit.id)?'red':'green'">{{twin.blocked.includes(exit.id)?'已封闭':'正常通行'}}</span></div></Panel>
    <Panel title="预警信息"><div class="alert-message"><Icon name="alert"/><div>{{overview.trapped?`${overview.trapped}人暂无安全路径，请检查出口状态。`:currentRisk.risk>.25?'火场风险正在上升，请使用动态安全路线。':twin.running?'演练进行中，保持安全出口畅通。':'模型已就绪，启动演练观察火烟与人员变化。'}}<small>来自当前仿真状态</small></div></div></Panel>
    <Panel title="事件日志" :tag="`${twin.events.length} 条`"><div class="event-list"><div v-for="(e,i) in twin.events.slice(-12).reverse()" :key="i"><time>{{format(e.time)}}</time><b :class="e.type.includes('警')?'red':'cyan'">{{e.type}}</b><span>{{e.message}}</span></div><p v-if="!twin.events.length" class="empty">等待演练启动</p></div></Panel>
   </aside>
  </main>
  <main v-else-if="page==='student'" class="student-layout">
   <div class="student-toolbar"><button @click="navigate('command')"><Icon name="back"/>返回指挥中心</button><span>当前演练场景：<b>宿舍楼火灾演练</b></span><b class="drill-badge" :class="{running:twin.running}">{{twin.student.escaped?'已到达安全区域':twin.running?'演练进行中':twin.finished?'演练已结束':twin.time?'演练已暂停':'待启动'}}</b><div>演练进度 <b class="red">{{format(twin.time)}}</b> / 10:00 <progress :value="twin.time" max="600"/></div><button class="primary" @click="start" :disabled="twin.finished"><Icon :name="twin.running?'pause':'play'"/>{{twin.running?'暂停演练':twin.time?'继续演练':'开始演练'}}</button></div>
   <aside><Panel title="当前位置 / 楼层平面图"><template #action><select v-model.number="floor" aria-label="平面图楼层"><option v-for="f in [6,5,4,3,2,1]" :value="f">{{f}}F</option></select></template><FloorMap :twin="twin" :floor="floor" @select="pick"/><div class="map-legend"><span class="green">推荐路线</span><span class="cyan">当前位置</span><span class="red">火源位置</span><span>楼梯出口</span></div></Panel><Panel title="演练任务" tag="TASKS"><div class="task-list"><div v-for="(task,i) in ['立即撤离宿舍楼','避开高烟区域，保持低姿','沿安全路线前往楼外出口','提醒并帮助周边同学']" :class="{done:i===1&&twin.student.crouching||i===3&&twin.student.actions.some(a=>a.type==='help')||i===0&&twin.student.escaped}"><b>{{i+1}}</b><div><h3>{{task}}</h3><small>{{['按照推荐路线安全撤离建筑','使用弯腰前进与湿毛巾防护','楼梯间下行至1F安全出口','呼救求助按钮记录提醒行为'][i]}}</small></div><Icon name="next"/></div></div></Panel><Panel title="推荐路线（当前）"><div class="route-steps"><div v-for="id in (studentRoute||[]).filter(id=>['stairs','exit'].includes(spaceById[id].kind))"><Icon name="exit"/><span>{{spaceById[id].name}}</span></div><p v-if="!studentRoute" class="red">暂无安全路径，等待出口恢复</p></div><div class="route-total">预计路程 <b>{{routeDistance===null?'—':Math.round(routeDistance)}} m</b></div><p class="source-foot">路线箭头来自实时 A* 寻路结果</p></Panel></aside>
   <div class="student-stage"><div class="student-world"><TwinScene :twin="twin" :floor="twin.student.floor" mode="student" :layer="showGuide?'routes':'student-no-route'" v-model:student-view="studentView" v-model:show-guide="showGuide" :model-url="modelUrl" @action="act" @notice="toast" @loaded="modelStatus='就绪'"/><div class="student-location"><Icon name="map"/>{{twin.student.floor}}F · {{spaceById[twin.student.node].name}}</div><div class="keyboard-guide"><span>WASD 移动 · Shift 疾走</span><span>拖动环视 · V 视角</span><span>C 弯腰 · F 防护 · E 交互</span></div><div class="student-warning"><Icon name="alert"/>{{twin.student.escaped?'你已到达安全区域，可查看演练评分。':studentField.risk>.15?'前方火烟风险上升，请保持低姿前进！':'沿地面绿色箭头前进，注意楼梯间。'}}</div><div v-if="twin.student.escaped" class="escaped-overlay"><Icon name="shield"/><h2>已安全撤离</h2><b>{{studentScore.toFixed(0)}} 分</b><button @click="modal='score'">查看演练报告</button></div></div><Panel title="演练提示 / 实时反馈"><div class="feedback-events"><div v-for="e in twin.events.slice(-5).reverse()"><time>{{format(e.time)}}</time><Icon name="check"/><span>{{e.message}}</span></div><p v-if="!twin.events.length">可先自由探索房间；开始演练后，沿推荐路线撤离。走近楼梯选择上楼或下楼。</p></div></Panel></div>
   <aside><Panel title="个人状态" tag="学员 · 本地演练"><div class="personal-grid"><div><Icon name="fire"/><span>烟气指数</span><b>{{studentField.smoke.toFixed(2)}}</b><progress :value="studentField.smoke" max="1"/></div><div><Icon name="speed"/><span>当前温度</span><b>{{studentField.temperature.toFixed(1)}} <small>℃</small></b><progress :value="(studentField.temperature-22)/100" max="1"/></div><div><Icon name="health"/><span>生命 / 安全值</span><b>{{twin.student.health.toFixed(0)}} <small>/ 100</small></b><progress :value="twin.student.health" max="100"/></div><div><Icon name="time"/><span>已用时间</span><b>{{format(twin.time)}}</b><small>剩余距离 {{routeDistance===null?'—':Math.round(routeDistance)}} m</small></div></div><div class="warning-box"><Icon name="alert"/><div><small>当前风险等级</small><h3>{{danger(studentField.risk)}}</h3><span>{{twin.student.crouching?'当前为低姿态':'当前为站立姿态'}} · {{twin.student.towel?'湿毛巾防护已开启':'未使用湿毛巾'}}</span></div></div></Panel><Panel title="环境变化趋势（当前演练）"><TwinChart kind="environment" :data="twin.history"/></Panel><Panel title="操作功能"><div class="operation-grid"><button @click="act('crouch')" :class="{active:twin.student.crouching}"><Icon name="walk"/>弯腰前进<small>{{twin.student.crouching?'当前状态':'点击切换'}}</small></button><button @click="act('towel')" :class="{active:twin.student.towel}"><Icon name="water"/>湿毛巾防护</button><button @click="act('door')"><Icon name="exit"/>{{nearbyRoom?(twin.closedDoors.includes(nearbyRoom.id)?'打开':'关闭')+nearbyRoom.number+'房门':'附近房门'}}</button><button @click="act('extinguisher')"><Icon name="fire"/>使用灭火器</button><button @click="act('help')"><Icon name="bell"/>呼救求助</button><button @click="modal='score'"><Icon name="report"/>演练评分</button></div></Panel></aside>
  </main>
  <main v-else-if="page==='teacher'" class="teacher-layout">
   <aside class="teacher-sidebar"><button v-for="[icon,name] in teacherMenu" :class="{active:teacherTab===name}" @click="teacherTab=name"><Icon :name="icon"/>{{name}}</button><div><Icon name="shield"/><p>校园安全</p><small>数字孪生 · 智慧应急</small></div></aside>
   <div class="teacher-content"><div class="teacher-kpis"><div v-for="k in [{icon:'calendar',label:'演练记录',value:records.length+(twin.finished?0:1),unit:'场'},{icon:'play',label:'正在进行演练',value:twin.running?1:0,unit:'场'},{icon:'map',label:'可用建筑场景',value:1,unit:'个'},{icon:'people',label:'本次演练人数',value:286,unit:'人'},{icon:'shield',label:'本次演练完成率',value:Math.round(overview.completion*100),unit:'%'},{icon:'report',label:'当前规则评分',value:overview.score.toFixed(1),unit:'分'}]"><div class="kpi-icon"><Icon :name="k.icon"/></div><div><span>{{k.label}}</span><b>{{k.value}} <small>{{k.unit}}</small></b><small class="green">本地演练数据</small></div></div></div>
    <div v-if="['演练管理','首页总览'].includes(teacherTab)" class="teacher-grid">
     <Panel title="本月演练计划" class="calendar-panel"><div class="calendar-header"><button @click="changeMonth(-1)" aria-label="上个月"><Icon name="prev"/></button><span>{{month.getFullYear()}}年{{month.getMonth()+1}}月</span><button @click="changeMonth(1)" aria-label="下个月"><Icon name="next"/></button><button @click="today">今天</button></div><div class="calendar-grid"><span v-for="d in ['一','二','三','四','五','六','日']">{{d}}</span><button v-for="(d,i) in calendarCells" :key="i" :disabled="!d" :class="{selected:d===selectedDay}" @click="selectedDay=d">{{d}}</button></div><h3 class="calendar-date">{{month.getMonth()+1}}月{{selectedDay}}日 · 演练安排</h3><div class="schedule-card" v-if="selectedDay===localToday[2]&&month.getMonth()===localToday[1]-1&&month.getFullYear()===localToday[0]"><h3>{{params.name}}</h3><p><Icon name="map"/>{{building.name}}</p><p><Icon name="people"/>{{overview.count}} 名虚拟学员</p><span class="status-chip">{{twin.running?'正在进行':twin.finished?'已完成':'准备启动'}}</span></div><button class="full-width" @click="modal='new'"><Icon name="add"/>新建演练计划</button></Panel>
     <Panel title="演练管理中心" class="drill-table-panel"><template #action><button class="primary" @click="modal='new'"><Icon name="add"/>新建演练</button></template><div class="filter-bar"><button v-for="filter in ['全部演练','计划中','进行中','已暂停','已完成']" :class="{active:statusFilter===filter}" @click="statusFilter=filter">{{filter}}</button></div><div class="table-wrap"><table><thead><tr><th>序号</th><th>演练名称</th><th>演练场景</th><th>参与人数</th><th>状态</th><th>时间</th><th>平均成绩</th><th>操作</th></tr></thead><tbody><tr v-for="(row,i) in rows"><td>{{String(i+1).padStart(2,'0')}}</td><td>{{row.name}}</td><td>{{row.scene}}</td><td>{{row.count}}</td><td><span class="status-chip" :class="{ongoing:row.status==='进行中'}">{{row.status}}</span></td><td>{{row.date}}</td><td>{{row.score===null?'—':row.score.toFixed(1)}}</td><td><button @click="row.id==='current'&&row.status!=='已完成'?navigate('command'):report(row)">{{row.id==='current'&&!twin.finished?'实时监控':'查看报告'}}</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">没有符合筛选条件的演练</p></div><div class="table-note">{{isPublicDemo?'公开演示记录仅保存在当前浏览器，可导出完整状态。':'演练摘要保存在本地数据库，可通过导出记录保存完整状态。'}}</div></Panel>
     <div class="teacher-stats"><Panel title="演练数据统计"><div class="teacher-stat-grid"><div><Icon name="people"/><span>参与人数</span><b>286 <small>人</small></b></div><div><Icon name="shield"/><span>完成率</span><b>{{Math.round(overview.completion*100)}}%</b></div><div><Icon name="chart"/><span>历史演练</span><b>{{records.length}} <small>场</small></b></div><div><Icon name="time"/><span>平均疏散时间</span><b>{{(overview.time/60).toFixed(1)}} <small>min</small></b></div></div></Panel><Panel title="当前演练疏散趋势"><TwinChart kind="trend" :data="twin.history"/></Panel></div>
     <Panel title="场景资源管理" class="resources-panel"><template #action><button @click="teacherTab='场景管理'">管理场景 <Icon name="next"/></button></template><div class="resource-row"><div class="resource-card"><img :src="assetUrl('/assets/dorm-preview.png')" alt="六层宿舍楼模型预览"><div><h3>宿舍楼火灾应急疏散</h3><span class="status-chip">六层宿舍</span><span class="status-chip">米制 GLB</span></div><button class="primary" @click="navigate('command')">使用场景</button></div><div class="resource-detail"><h3>{{building.name}} · 参数化建筑底座</h3><div class="spec-grid"><span>建筑层数 <b>6 层</b></span><span>占地尺寸 <b>48 × 18 m</b></span><span>标准层高 <b>3.3 m</b></span><span>走廊净宽 <b>2.4 m</b></span><span>宿舍开间 / 进深 <b>4.2 × 6.8 m</b></span><span>空间语义 <b>{{spaces.length}} 个</b></span></div><p>模型尺寸根据参考图与宿舍尺度建立，未经实测。支持查看 IFC、GLB 和空间拓扑。</p><button @click="modal='model'">模型、尺寸与数据接入</button></div></div></Panel>
    </div>
    <Panel v-else-if="teacherTab==='场景管理'" title="场景管理 / 建筑数字底座"><div class="model-management"><div><h3>{{building.name}}</h3><p>六层双面宿舍 · 108间宿舍 · 三处楼梯 · 四个安全出口</p><div class="spec-grid"><span v-for="[key,value] in [['长度',48],['宽度',18],['层高',3.3],['走廊宽度',2.4],['楼梯宽度',1.4],['门宽',1]]">{{key}} <b>{{value}} m</b></span></div><p>建筑尺寸为参数化假设，真实楼栋需要用实测或 BIM 数据替换并校核。</p><div class="inline-actions"><a :href="assetUrl('/models/dormitory.glb')" download>下载 GLB</a><a :href="assetUrl('/models/dormitory.ifc')" download>下载 IFC</a><a :href="assetUrl('/models/building.json')" download>下载空间拓扑</a><button @click="modal='model'">替换模型 / 接入数据</button></div></div><FloorMap :twin="twin" :floor="floor" @select="pick"/></div></Panel>
    <Panel v-else-if="teacherTab==='学生管理'" title="演练人员状态"><div class="table-wrap personnel-table"><table><thead><tr><th>学员编号</th><th>初始楼层</th><th>当前区域</th><th>疏散状态</th><th>累计风险暴露</th><th>等待时间</th></tr></thead><tbody><tr v-for="a in twin.agents"><td>SIM-{{String(a.id).padStart(3,'0')}}</td><td>{{a.originFloor}}F</td><td>{{spaceById[a.node].name}}</td><td :class="a.escaped?'green':a.trapped?'red':'cyan'">{{a.escaped?'已撤离':a.trapped?'暂无路径':'待撤离 / 移动中'}}</td><td>{{a.exposure.toFixed(2)}}</td><td>{{a.wait.toFixed(1)}} s</td></tr></tbody></table></div></Panel>
    <Panel v-else-if="teacherTab==='评分报告'" title="演练评分报告"><div class="score-report"><b>{{overview.score.toFixed(1)}}<small>/ 100</small></b><div v-for="[key,name] in [['completion','完成率 · 40%'],['efficiency','时间效率 · 20%'],['avoidance','风险规避 · 25%'],['flow','通行效率 · 15%']]"><span>{{name}}</span><progress :value="overview.dimensions[key]" max="100"/><strong>{{overview.dimensions[key].toFixed(1)}}</strong></div><button @click="exportTwin"><Icon name="download"/>导出完整评分与事件</button></div></Panel>
    <Panel v-else-if="teacherTab==='预案管理'" title="预案管理 / 对比评估"><div class="model-management"><div><h3>方案A：就近疏散</h3><p>考虑路径长度与火烟风险，优先选择临近安全出口。</p><h3>方案B：动态分流</h3><p>同时考虑火烟风险和节点人员密度，每秒更新路径。</p><button class="primary" @click="navigate('review');compare()">运行 A/B 对比</button></div></div></Panel>
    <Panel v-else title="系统设置 / 软件数据接口"><div class="model-management"><div><h3>Twin State 统一状态接口</h3><p>传感器接口预留，当前无需硬件。标准消息包含建筑ID、空间ID与温度、烟气、火势状态。</p><pre>{{JSON.stringify(interfaceContract,null,2)}}</pre><button @click="download(interfaceContract,'twin-interface.json')">下载接口样例</button><button @click="modal='model'">导入火烟场数据</button></div></div></Panel>
   </div>
  </main>
  <main v-else class="review-layout">
   <aside><Panel title="演练回放与事件时间轴"><div class="replay-select">{{building.name}} · {{params.name}}</div><div class="replay-controls"><b>{{format(replay?.time||0)}} <small>/ {{format(twin.time)}}</small></b><button @click="replayPlaying=!replayPlaying" :disabled="!twin.snapshots.length" :aria-label="replayPlaying?'暂停回放':'播放回放'"><Icon :name="replayPlaying?'pause':'play'"/></button></div><input class="replay-slider" type="range" min="0" :max="Math.max(0,twin.snapshots.length-1)" v-model.number="replayIndex" :disabled="!twin.snapshots.length" aria-label="演练回放进度"><div class="speed-buttons"><button v-for="speed in [.5,1,2,4]" :class="{active:replaySpeed===speed}" @click="replaySpeed=speed">{{speed}}x</button></div><div class="timeline"><div v-for="(e,i) in twin.events.filter(e=>!e.type.includes('路径')).slice(-12)" :key="i"><time>{{format(e.time)}}</time><Icon :name="e.type.includes('火')?'fire':e.type.includes('结束')?'check':'walk'"/><div><h3>{{e.type}}</h3><p>{{e.message}}</p></div></div><p v-if="!twin.events.length" class="empty">先完成一次演练以查看回放</p></div></Panel></aside>
   <div class="review-center"><div class="scene-panel"><div class="scene-title"><h2>{{building.name}} · {{floor}}F 平面疏散热力图</h2><span>演练回放 {{format(replay?.time||0)}}</span></div><TwinScene :twin="twin" :floor="floor" :mode="sceneMode" :layer="layer" :replay="replay" :model-url="modelUrl" @select="pick" @loaded="modelStatus='就绪'"/><div class="floor-switch"><button v-for="f in [6,5,4,3,2,1]" :class="{active:floor===f}" @click="floor=f">{{f}}F</button></div><div class="heat-legend"><b>综合风险 / 人员密度</b><span class="red">高风险 / 高密度</span><span class="yellow">中等</span><span class="green">低风险</span><span class="cyan">正常</span></div><div class="scene-bottom"><div class="scene-tabs"><button :class="{active:layer==='heat'}" @click="layer='heat'">热力分布</button><button :class="{active:layer==='people'}" @click="layer='people'">人员轨迹</button><button :class="{active:layer==='smoke'}" @click="layer='smoke'">烟气扩散</button><button :class="{active:layer==='routes'}" @click="layer='routes'">疏散路径</button><button @click="sceneMode=sceneMode==='floor'?'top':'floor'">切换视角</button></div></div></div><div class="review-bottom"><Panel title="疏散时间分布对比"><TwinChart v-if="comparison" kind="comparison" :data="comparison"/><div v-else class="empty-comparison"><Icon name="chart"/><p>使用相同条件运行两种策略</p><button @click="compare" :disabled="comparing">{{comparing?'算法计算中…':'运行 A/B 对比'}}</button></div></Panel><Panel title="各楼层撤离效率"><table class="floor-efficiency"><thead><tr><th>楼层</th><th>人员总数</th><th>已疏散</th><th>完成率</th></tr></thead><tbody><tr v-for="f in [...overview.floors].reverse()"><td>{{f.floor}}F</td><td>{{f.total}}</td><td>{{f.escaped}}</td><td><progress :value="f.total?f.escaped/f.total:0" max="1"/>{{f.total?Math.round(f.escaped/f.total*100):0}}%</td></tr></tbody></table></Panel></div></div>
   <aside><Panel title="方案A/B 对比分析"><template #action><button class="primary" @click="compare" :disabled="comparing">{{comparing?'计算中…':'重新计算'}}</button></template><table class="comparison-table"><thead><tr><th></th><th class="red">方案A<small>就近疏散</small></th><th class="green">方案B<small>动态分流</small></th></tr></thead><tbody><tr v-for="[key,label,unit] in [['time','平均疏散时间','min'],['wait','平均等待时间','s'],['peakDensity','峰值节点密度','人/m²'],['completion','疏散完成率','%'],['score','预案评分','分'],['exposure','平均风险暴露','']]"><td>{{label}}</td><td v-for="c in comparison||[null,null]">{{c?(key==='time'?c[key]/60:key==='completion'?c[key]*100:c[key]).toFixed(1):'—'}} <small>{{unit}}</small></td></tr></tbody></table><p class="source-foot">相同建筑 / 火源 / 286人 / 种子{{params.seed}}，结果来自算法实际运行。</p></Panel><Panel title="瓶颈分析（当前演练）"><div class="bottlenecks"><div v-for="(n,i) in spaces.filter(n=>n.kind==='stairs'||n.kind==='corridor').sort((a,b)=>twin.fields[b.id].density-twin.fields[a.id].density).slice(0,3)"><b>{{i+1}}</b><div><h3>{{n.name}}</h3><p>当前密度 <strong>{{twin.fields[n.id].density.toFixed(2)}} 人/m²</strong></p><small>风险 {{Math.round(twin.fields[n.id].risk*100)}} / 100</small></div><Icon name="alert"/></div></div></Panel><Panel title="优化建议与决策结论"><div class="recommendations"><div><b>1</b><span><strong>保持多个出口畅通</strong><small>{{twin.blocked.length?`当前有${twin.blocked.length}处出口封闭，建议检查可用性。`:'当前四个出口均可用，支持人员分流。'}}</small></span></div><div><b>2</b><span><strong>对比拥堵权重的实际效果</strong><small>{{comparison?`动态分流平均等待${comparison[1].wait.toFixed(1)}秒，就近疏散${comparison[0].wait.toFixed(1)}秒。`:'运行A/B对比后评估等待时间与风险暴露。'}}</small></span></div><div><b>3</b><span><strong>校核火烟模型与建筑尺寸</strong><small>当前为软件教学仿真，可导入外部火烟场数据进行回放。</small></span></div></div><button class="full-width" @click="exportTwin"><Icon name="download"/>导出复盘与预案对比</button></Panel></aside>
  </main>
  <div v-if="notice" class="toast" role="status"><Icon name="check"/>{{notice}}</div>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=null"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal==='new'?'新建演练':'模型与演练信息'"><div class="modal-heading"><h2>{{modal==='new'?'新建应急疏散演练':modal==='model'?'建筑模型与数据接入':'演练评分报告'}}</h2><button @click="modal=null" aria-label="关闭对话框"><Icon name="close"/></button></div>
   <form v-if="modal==='new'" @submit.prevent="createDrill"><label>演练名称<input v-model="params.name" required maxlength="50"></label><label>火源位置<select v-model="params.source"><option v-for="r in rooms" :value="r.id">{{r.floor}}F · {{r.name}}</option></select></label><label>疏散策略<select v-model="params.strategy"><option value="balanced">动态分流：风险 + 拥堵</option><option value="nearest">就近疏散：距离 + 风险</option></select></label><label>随机种子<input v-model.number="params.seed" type="number" min="0" max="4294967295" required></label><p>新建演练将重置当前状态。已完成的演练保存在历史记录中。</p><button class="primary full-width" type="submit">创建演练</button></form>
   <div v-else-if="modal==='model'" class="model-dialog"><h3>{{building.name}} · 米制参数化模型</h3><div class="spec-grid"><span>长 × 宽 <b>48 × 18 m</b></span><span>标准层高 <b>3.3 m</b></span><span>走廊净宽 <b>2.4 m</b></span><span>宿舍开间 / 进深 <b>4.2 × 6.8 m</b></span></div><p>参考图确定外观方向，尺寸由参数化假设建立；模型未经现场测量，不能宣称与某栋真实楼宇1:1一致。</p><div class="inline-actions"><a :href="assetUrl('/models/dormitory.glb')" download>下载 GLB</a><a :href="assetUrl('/models/dormitory.ifc')" download>下载 IFC</a><a :href="assetUrl('/models/building.json')" download>空间拓扑 JSON</a></div><hr><h3>GLB模型接入</h3><p>模型应为米制、Y向上，并在楼层节点 extras 中含 floor:1…6。替换模型须匹配现有 dorm-01 坐标和空间拓扑。</p><label class="upload-button">选择 GLB 模型<input type="file" accept=".glb" @change="importModel"></label><button @click="modelUrl=assetUrl('/models/dormitory.glb');toast('已恢复参数化宿舍模型')">恢复默认模型</button><hr><h3>FDS / 外部场数据</h3><p>支持标准化CSV；FDS原始设备输出需先用转换脚本映射到空间ID。烟气指数为0–1归一化值，不等同于真实能见度。</p><code>time,space_id,temperature_c,smoke_index,fire_index</code><div class="inline-actions"><label class="upload-button">导入场数据 CSV<input type="file" accept=".csv" @change="importFds"></label><a :href="assetUrl('/data/field-template.csv')" download>下载格式样例</a></div><hr><h3>传感器预留接口</h3><p>MQTT / WebSocket 通过标准Twin State消息接入，当前没有传感器连接。</p><button @click="download(interfaceContract,'twin-interface.json')">下载接口规范样例</button></div>
   <div v-else class="score-report"><b>{{modal?.type==='report'?modal.row.score.toFixed(1):overview.score.toFixed(1)}}<small>/ 100</small></b><div v-for="[key,name] in [['completion','完成率 · 40%'],['efficiency','时间效率 · 20%'],['avoidance','风险规避 · 25%'],['flow','通行效率 · 15%']]"><span>{{name}}</span><progress :value="modal?.type==='report'?modal.row.metrics.dimensions[key]:overview.dimensions[key]" max="100"/><strong>{{(modal?.type==='report'?modal.row.metrics.dimensions[key]:overview.dimensions[key]).toFixed(1)}}</strong></div><p>规则评分：完成率40%、时间效率20%、累积风险规避25%、等待效率15%。</p><p v-if="page==='student'">个人操作分 {{studentScore.toFixed(0)}}：撤离60分、低姿10分、防护10分、关门及提醒10分、风险规避10分。当前{{twin.student.escaped?'已撤离':'尚未撤离'}}。</p><button @click="exportTwin"><Icon name="download"/>导出完整记录</button></div>
  </section></div>
 </div>
</template>



